if (msg.req.files && msg.req.files.length > 0) {
    const file = msg.req.files[0];

    msg.member_id = msg.req.body?.id || null;
    msg.session_id = msg.req.headers['x-session-id'];

    if (!msg.member_id) {
        msg.payload = { error: "Missing member 'id' in multipart body" };
        msg.statusCode = 400;
        msg._responded = true;
        return [null, msg];
    }

    if (!msg.session_id) {
        msg.payload = { error: "Missing 'X-Session-Id' header" };
        msg.statusCode = 400;
        msg._responded = true;
        return [null, msg];
    }

    msg.original_image_data = {
        buffer: file.buffer,
        filename: file.originalname,
        mimetype: file.mimetype
    };

    msg.payload = {
        image: {
            value: file.buffer,
            options: {
                filename: file.originalname,
                contentType: file.mimetype
            }
        }
    };

    msg.headers = { 'content-type': 'multipart/form-data' };
    return [msg, null];
}

msg.payload = { error: "No file uploaded" };
