return [null, msg];

const TH = 0.5;
const score = Number(msg.payload?.score);

if (Number.isNaN(score) || score < TH) {
    msg.payload = { error: 'No valid face detected (score < 0.5)' };
    msg.statusCode = 400;
    msg._responded = true;
    return [null, msg];
}

return [msg, null];

