msg.url = `http://localhost:8080/garAItu/member/${msg.member_id}/embedding`;
msg.headers = {
    'Content-Type': 'application/json',
    'X-Session-Id': msg.session_id
};

msg.payload = { embeddingBase64: buffer.toString('base64') };
return [msg, null];

if (msg._responded) return null;

msg.payload = { error: msg.payload?.error || msg.error || 'Unknown error' };
msg.statusCode = msg.statusCode || 400;
msg._responded = true;
