}
return msg;

msg.payload = { error: msg.error ? msg.error.message : 'Unknown error' };
msg.statusCode = 500;
return msg;

const TH = flow.get('face_threshold') ?? 0.5;
const p = msg.payload || {};
const score = Number(p.score);

if (Number.isNaN(score)) {
    msg.error = { code: 'NO_SCORE', message: 'Missing/invalid score' };
    msg.status = 400;
    return [null, msg];
}

msg.metrics = {
    first_model_score: score,
    threshold: TH
};

if (score >= TH) {
    msg.route = 'to_uniface';
    return [msg, null];
}

msg.route = 'skip_uniface';
msg.result = {
    recognized: false,
    reason: 'score_below_threshold',
    score
};
msg.status = 200;
return [null, msg];

// Recuperar imagen original guardada
if (msg.original_image_data) {
    msg.payload = {
        "image": {
            "value": msg.original_image_data.buffer,
            "options": {
                "filename": msg.original_image_data.filename,
                "contentType": msg.original_image_data.mimetype
            }
        }
    };
    // Limpiar headers anteriores y forzar multipart
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';
} else {
   // Fallback si no hay imagen (error?)
   msg.payload = {};
}

// No necesitamos Authorization por ahora si es local
