return msg;

// Normaliza la respuesta del microservicio
const t = msg._t0 || Date.now();
const latency = Date.now() - t;
const resp = msg.payload || {};
const pf = resp.primary_face || {};
let embeddingBase64 = null;
if (resp.embedding && Array.isArray(resp.embedding)) {
    const floatArray = new Float32Array(resp.embedding);
    const buffer = Buffer.from(floatArray.buffer);
    embeddingBase64 = buffer.toString('base64');
}

// 2. Configurar llamada REST
if (embeddingBase64) {
    msg.payload = {
        embeddingBase64: embeddingBase64,
        minSim: 0.4,
        top: 5
    };

    // Headers
    msg.headers = {};
    msg.headers['Content-Type'] = 'application/json';
    if (msg.session_id) {
        msg.headers['X-Session-Id'] = msg.session_id;
    }

    // URL endpoint Java
    msg.url = `http://localhost:8080/garAItu/group/${msg.group_id}/recognize`;

    msg.metrics = msg.metrics || {};
    msg.metrics.uniface_latency_ms = latency;
    msg.local_result = { recognized: !!resp.recognized, primary_face: pf };

    // SALIDA 1: Al REST
    return [msg, null];
} else {
    // Si no hubo cara, no llamamos al REST. Respondemos directo.
    msg.payload = { recognized: false, reason: "No embedding generated" };

    msg.metrics = msg.metrics || {};
    msg.metrics.uniface_latency_ms = latency;
    msg.local_result = { recognized: false, primary_face: pf };

    // SALIDA 2: Directo a Response
    return [null, msg];
}

// 1. Obtenemos la respuesta del servidor Java
