msg.similarity = Math.round(bestMatch.similarity * 100) / 100;
// 5. CONSTRUIMOS EL MENSAJE TTS
// Dirá algo como: "This person is Josu and this is his context: He is your son who lives in Madrid"
msg.ttsText = `${msg.recognizedName} ${contextFromDB}.`;
// 6. Enviamos al siguiente nodo (Piper)
return [msg, null];

// Guardamos los datos para que no se pierdan cuando Piper responda
