function validate(obj, schema) {
  const errors = [];
  const has = (k) => obj && Object.prototype.hasOwnProperty.call(obj, k);

  (schema.required || []).forEach((k) => {
    if (!has(k) || obj[k] === null || obj[k] === "") errors.push(`Missing '${k}'`);
  });

  if (schema.properties) {
    for (const [k, rule] of Object.entries(schema.properties)) {
      if (!has(k)) continue;
      const v = obj[k];

      if (rule.type === "string" && typeof v !== "string") errors.push(`'${k}' must be string`);
      if (rule.minLength && typeof v === "string" && v.length < rule.minLength) errors.push(`'${k}' too short`);
      if (rule.pattern && typeof v === "string" && !(new RegExp(rule.pattern).test(v))) {
        errors.push(`'${k}' invalid format`);
      }
    }
  }
  return errors;
}

