  return [null, msg];
}

const p = msg.payload || {};
const errors = [];

// email
if (!p.email) errors.push("Missing 'email'");
else if (!isEmail(p.email)) errors.push("'email' invalid format");

// password (mínimo 1 char, si quieres mínimo 6 te lo cambio)
if (p.password === undefined || p.password === null || p.password === "") {
  errors.push("Missing 'password'");
}

// role: admite number o string numérico
if (p.role === undefined || p.role === null || p.role === "") {
  errors.push("Missing 'role'");
} else {
  const roleNum = typeof p.role === "number" ? p.role : parseInt(String(p.role), 10);
  if (!Number.isInteger(roleNum)) errors.push("'role' must be integer");
  else if (![1, 2].includes(roleNum)) errors.push("'role' must be 1 or 2");
  else p.role = roleNum; // normalizamos para Spring Boot
}

// name (mínimo 1 caracter real)
if (p.name === undefined || p.name === null) {
  errors.push("Missing 'name'");
} else if (typeof p.name !== "string") {
  errors.push("'name' must be string");
} else if (p.name.trim().length < 1) {
  errors.push("'name' too short");
}

// chatId (permitimos "" pero si viene que sea string)
if (p.chatId !== undefined && typeof p.chatId !== "string") {
  errors.push("'chatId' must be string");
}

// context (opcional, puede ser "" si te da igual)
if (p.context !== undefined && typeof p.context !== "string") {
  errors.push("'context' must be string");
}

if (errors.length) return bad(400, errors);

// OK
msg.payload = p;
return [msg, null];
